SET NAMES utf8mb4;









UPDATE contents c
JOIN (
    SELECT content_id, COUNT(*) AS cnt, SUM(rating) AS s
    FROM reviews
    WHERE status = 'COMPLETED'
    GROUP BY content_id
) r ON r.content_id = c.id
SET c.review_count = r.cnt,
    c.rating_sum = r.s,
    c.average_rating = ROUND(r.s / r.cnt, 1);